async function setWindowsAutoHibernate(enabled){if(windowsAutoPowerSaving)return;windowsAutoPowerSaving=true;const toggle=$('#windowsAutoHibernate');if(toggle)toggle.disabled=true;try{const policy=await api('/api/windows-power-policy',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({auto_hibernate_enabled:enabled})});windowsAutoHibernateEnabled=policy.auto_hibernate_enabled;note(enabled?'큐 완료 후 자동 최대절전을 켰습니다.':'자동 종료를 껐습니다. Windows PC를 켜 둡니다.')}catch(error){note(error.message,true)}finally{windowsAutoPowerSaving=false;const current=$('#windowsAutoHibernate');if(current){current.checked=windowsAutoHibernateEnabled===true;current.disabled=windowsAutoHibernateEnabled===null}refreshSystemMetrics()}}
