function h3RerenderRiskMessage(width,height,duration=0,referenceCount=0,estimate=null){const pixels=Number(width)*Number(height),condition=`현재 후보 ${Number(duration)||'-'}초 · Picture ${Number(referenceCount)||0}장`,minutes=value=>value?`${(Number(value)/60).toFixed(1)}분`:'-',examples=(estimate?.examples||[]).map(item=>`${item.clip_id} (${item.duration_seconds}초·${item.reference_count}장·${minutes(item.elapsed_seconds)})`).join(', ');let evidence='실측 자료가 부족해 보수적으로 판단합니다.';if(estimate?.exact_success_count>0)evidence=`동일 조건 성공 ${estimate.exact_success_count}건 · 중앙 ${minutes(estimate.median_seconds)} · 범위 ${minutes(estimate.low_seconds)}~${minutes(estimate.high_seconds)}${examples?` · 성공 사례 ${examples}`:''}.`;else if(estimate?.sample_count>0)evidence=`동일 조건 성공 기록은 없으며, 가까운 성공 ${estimate.sample_count}건 기준 예상 중앙 ${minutes(estimate.median_seconds)} · 범위 ${minutes(estimate.low_seconds)}~${minutes(estimate.high_seconds)}${examples?` · 참고 사례 ${examples}`:''}.`;const failure=estimate?.exact_failure_count?` 동일 조건 실패 ${estimate.exact_failure_count}건이 있으며 이전 큐 추적 오류도 포함됩니다.`:'';const unverified=Number(referenceCount)>Number(estimate?.max_successful_reference_count||0)&&Number(estimate?.max_successful_reference_count||0)>0?` 이 해상도의 성공 기록은 Picture ${estimate.max_successful_reference_count}장까지이며 ${referenceCount}장은 아직 성공 근거가 없습니다.`:'';const high=pixels>=1280*704&&(unverified||estimate?.exact_failure_count>0||Number(estimate?.high_seconds)>=3600);const lead=high?'고부하 경고':pixels>=1280*704?'고해상도 실측 안내':'실측 안내';return`${lead}: ${condition}. ${evidence}${failure}${unverified}${pixels>=1280*704?' 통합 메모리 압박이나 장시간 응답 지연으로 실패할 수 있으며, 안정성이 중요하면 1024 × 576을 권장합니다.':' 로컬 큐에서 한 작업씩 순차 처리됩니다.'}`}
