function resetH3FrameExport(jobId){h3FrameExportState={jobId,export:null,selected:new Set(),busy:false};const grid=$('#h3FrameGrid'),actions=$('#h3FrameActions'),status=$('#h3FrameStatus'),button=$('#h3FrameExtract');if(grid)grid.innerHTML='';if(actions)actions.hidden=true;if(button)button.disabled=!jobId;if(status)status.textContent='필요한 간격을 골라 추출하세요. 추출은 이 버튼을 누를 때만 실행됩니다.'}
