function renderH3FrameExport(){const state=h3FrameExportState,out=state.export,grid=$('#h3FrameGrid'),actions=$('#h3FrameActions'),all=$('#h3FrameDownloadAll');if(!grid||!out)return;grid.innerHTML=(out.frames||[]).map(frame=>`<article class="h3-frame-card" data-h3-frame="${esc(frame.filename)}"><button type="button" class="h3-frame-seek" data-h3-frame-seek="${esc(frame.time_seconds)}" title="영상에서 이 시점 보기"><img src="${esc(h3FrameFileUrl(frame.preview_filename))}" alt="${esc(frame.time_seconds)}초 프레임" loading="lazy"></button><div class="h3-frame-card-meta"><label><input type="checkbox" data-h3-frame-check="${esc(frame.filename)}">${Number(frame.time_seconds).toFixed(2)}초 · f${esc(frame.frame_index)}</label>${(()=>{const name=h3FrameLabeled()&&frame.labeled_filename?frame.labeled_filename:frame.filename;return `<a href="${esc(h3FrameFileUrl(name,true))}" download="${esc(name)}">PNG</a>`})()}<button type="button" data-h3-frame-annotate="${esc(frame.filename)}">그리며 검수 <span data-annotation-badge></span></button></div></article>`).join('');if(all){const name=h3FrameLabeled()&&out.labeled_zip_filename?out.labeled_zip_filename:out.zip_filename;all.href=h3FrameFileUrl(name,true);all.setAttribute('download',name);all.textContent=`전체 ${(out.frames||[]).length}장 ZIP`}if(actions)actions.hidden=false;$$('[data-h3-frame-check]').forEach(box=>box.onchange=()=>{const name=box.dataset.h3FrameCheck;if(box.checked)state.selected.add(name);else state.selected.delete(name);updateH3FrameSelection()});$$('[data-h3-frame-seek]').forEach(button=>button.onclick=()=>{const video=$('#h3CandidateVideo');if(!video)return;video.pause();video.currentTime=Number(button.dataset.h3FrameSeek)});updateH3FrameSelection();bindH3FrameAnnotations()}
function bindH3FrameAnnotations(){const state=h3FrameExportState;$$('[data-h3-frame-annotate]').forEach(button=>button.onclick=()=>{const frameIndex=state.export.frames.findIndex(frame=>frame.filename===button.dataset.h3FrameAnnotate);$('#h3CandidateVideo')?.pause();window.H3FrameAnnotator.open({jobId:state.jobId,tag:state.export.interval_tag,frames:state.export.frames,index:frameIndex,title:$('#h3CandidateVideoTitle').textContent})});api(`/api/h3/jobs/${encodeURIComponent(state.jobId)}/frames/${encodeURIComponent(state.export.interval_tag)}/annotations`).then(out=>{if(state!==h3FrameExportState)return;$$('[data-h3-frame-annotate]').forEach(button=>{button.querySelector('[data-annotation-badge]').textContent=out.saved.includes(button.dataset.h3FrameAnnotate)?'· 저장됨':''})}).catch(()=>{})}
window.addEventListener('h3-frame-annotation-saved',event=>{if(event.detail.jobId!==h3FrameExportState.jobId)return;$$('[data-h3-frame-annotate]').forEach(button=>{if(button.dataset.h3FrameAnnotate===event.detail.filename)button.querySelector('[data-annotation-badge]').textContent='· 저장됨'})});
async function extractH3Frames(){const state=h3FrameExportState,jobId=state.jobId,interval=$('#h3FrameInterval')?.value||'0.5',status=$('#h3FrameStatus'),button=$('#h3FrameExtract');if(!jobId||state.busy)return;state.busy=true;if(button)button.disabled=true;if(status)status.textContent=`${interval}초 간격으로 프레임을 추출하는 중입니다…`;try{const out=await api(`/api/h3/jobs/${encodeURIComponent(jobId)}/frames`,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({interval})});if(h3FrameExportState!==state)return;state.export=out;state.selected=new Set();renderH3FrameExport();if(status)status.textContent=`${out.interval_seconds}초 간격 ${out.frames.length}장 · ${out.width}×${out.height} · ${Number(out.fps).toFixed(2)}fps${out.cached?' · 이전 추출 결과 재사용':''}. 필요한 프레임을 선택해 받으세요.`}catch(error){const message=String(error.message||error).trim().split('\n').pop();if(status)status.textContent=`추출 실패: ${message}`;note(message,true)}finally{state.busy=false;if(button&&h3FrameExportState===state)button.disabled=false;updateH3FrameSelection()}}
async function downloadSelectedH3Frames(){const state=h3FrameExportState,out=state.export,status=$('#h3FrameStatus');if(!out||!state.selected.size||state.busy)return;state.busy=true;updateH3FrameSelection();try{const zip=await api(`/api/h3/jobs/${encodeURIComponent(state.jobId)}/frames/${encodeURIComponent(out.interval_tag)}/selection-zip`,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({filenames:[...state.selected],labeled:h3FrameLabeled()})});const link=document.createElement('a');link.href=h3FrameFileUrl(zip.zip_filename,true);link.download=zip.zip_filename;document.body.append(link);link.click();link.remove();if(status)status.textContent=`선택 ${zip.frame_count}장 ZIP(${zip.labeled?'시간·프레임 표시':'원본'})을 내려받습니다: ${zip.zip_filename}`}catch(error){note(error.message,true)}finally{state.busy=false;updateH3FrameSelection()}}
let h3PicturePreviewDownload={src:'',filename:''};
function clearH3PicturePreviewSource(){const image=$('#h3PicturePreviewImage');if(image){image.removeAttribute('src');image.alt=''}const meta=$('#h3PicturePreviewMeta');if(meta)meta.textContent='';h3PicturePreviewDownload={src:'',filename:''};const download=$('#h3PicturePreviewDownload');if(download){download.disabled=true;download.textContent='원본 다운로드'}}
