function h3PictureFilename(value,type=''){let name=String(value||'').split(/[\\/]/).pop().split(/[?#]/)[0].replace(/[<>:"/\\|?*\u0000-\u001f]/g,'_').trim(),extension=type==='image/jpeg'?'jpg':type==='image/webp'?'webp':'png';if(!name)name=`h3-picture.${extension}`;else if(!/\.(png|jpe?g|webp)$/i.test(name))name+=`.${extension}`;return name}
function openH3PicturePreview(src,title,meta='',filename=''){const dialog=$('#h3PicturePreviewDialog'),image=$('#h3PicturePreviewImage'),titleBox=$('#h3PicturePreviewTitle'),metaBox=$('#h3PicturePreviewMeta'),download=$('#h3PicturePreviewDownload');if(!dialog||!image||!titleBox||!metaBox||!download||!src)return;closeH3PicturePreview();titleBox.textContent=title||'Picture 참조 이미지';metaBox.textContent=meta;image.src=src;image.alt=title||'Picture 참조 이미지 확대 보기';h3PicturePreviewDownload={src,filename:filename||title||'h3-picture'};download.disabled=false;dialog.showModal()}
async function downloadH3PicturePreview(){const {src,filename}=h3PicturePreviewDownload,button=$('#h3PicturePreviewDownload');if(!src||!button)return;const original=button.textContent;try{button.disabled=true;button.textContent='다운로드 준비 중…';let key=sessionStorage.getItem('h3-key')||'',headers={};if(key)headers['x-access-key-b64']=asciiKey(key);let response=await fetch(src,{headers});if(response.status===401){clearRejectedAccessKey(key);key=await requestAccessKey();if(!key)throw Error('Picture 다운로드가 취소되었습니다.');headers={'x-access-key-b64':asciiKey(key)};response=await fetch(src,{headers})}if(!response.ok){let message=`Picture 다운로드 오류 ${response.status}`;try{message=(await response.json()).error||message}catch{}throw Error(message)}const blob=await response.blob(),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=h3PictureFilename(filename,blob.type);document.body.appendChild(link);link.click();link.remove();URL.revokeObjectURL(url);note(`Picture 원본 다운로드: ${link.download}`)}catch(error){note(error.message,true)}finally{if(button.isConnected){button.disabled=!h3PicturePreviewDownload.src;button.textContent=original}}}
function h3CandidateStoryboardReferences(set){return(set?.references||[]).filter(reference=>{const role=String(reference?.role||'').toLowerCase(),kind=String(reference?.reference_kind||'').toLowerCase();return kind==='storyboard'||role.includes('storyboard')})}
