const h3CandidateTerminalStatuses=new Set(['completed','failed','cancelled']);
function h3CandidateSetRuntimeState(set){const statuses=(set?.candidate_job_ids||[]).map(id=>String(h3Job(id)?.status?.status||'missing')),terminal=statuses.length>0&&statuses.every(status=>h3CandidateTerminalStatuses.has(status));return{terminal,active:!terminal,cancelRequested:!!set?.cancel_requested}}
