function syncH3CandidatePageBulkActions(){const sets=h3CandidatePageSets(),queued=sets.filter(h3CandidateQueuedOnly),deletable=sets.filter(set=>h3CandidateSetRuntimeState(set).terminal&&!h3CandidateSetHasSelection(set)),force=$('#forceStopH3CandidatePage'),remove=$('#deleteH3CandidatePage');if(force){force.disabled=!queued.length;force.title=queued.length?`현재 페이지의 실행 전 후보군 ${queued.length}개만 강제종료합니다.`:'현재 페이지에 실행 전 대기 후보군이 없습니다.'}if(remove){remove.disabled=!deletable.length;remove.title=deletable.length?`현재 페이지의 미선택 종료 후보군 ${deletable.length}개를 삭제합니다.`:'현재 페이지에 삭제 가능한 미선택 종료 후보군이 없습니다.'}}
async function forceStopH3CandidatePage(){const targets=h3CandidatePageSets().filter(h3CandidateQueuedOnly);if(!targets.length){note('현재 페이지에 실행 전 대기 후보군이 없습니다.',true);return}if(!confirm(`현재 필터와 페이지에 표시된 후보군 중 실행 전 대기 후보군 ${targets.length}개만 강제종료할까요?\n\n이미 실행 중인 후보군과 완료된 결과는 건드리지 않습니다.`))return;const button=$('#forceStopH3CandidatePage');try{button.disabled=true;let stopped=0,skipped=0;for(const set of targets){const out=await api(`/api/h3/queue-groups/${encodeURIComponent(set.candidate_set_id)}/force-stop`,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({queued_only:true})});if(String(out.status||'').startsWith('skipped_'))skipped++;else stopped++}await refreshH3State(true);note(`페이지 큐 강제종료 완료 · 처리 ${stopped}개${skipped?` · 실행 시작으로 제외 ${skipped}개`:''}`)}catch(error){note(error.message,true);await refreshH3State(true)}finally{syncH3CandidatePageBulkActions()}}
