async function deleteH3CandidateSet(setId){const set=(h3State.candidate_sets||[]).find(row=>row.candidate_set_id===setId);if(set&&h3CandidateSetHasSelection(set)){note('선택된 후보가 있어 삭제할 수 없습니다. 먼저 후보 선택을 취소하세요.',true);return}if(!confirm(`후보군 ${setId}을(를) 목록에서 제외할까요?\n\n선택된 후보군은 삭제할 수 없습니다. 생성 영상과 작업 기록, 소스는 보존됩니다.`))return;try{const out=await api(`/api/h3/candidate-sets/${encodeURIComponent(setId)}`,{method:'DELETE',headers:{'content-type':'application/json'},body:'{}'});await refreshH3State(true);note(`H3 후보군을 목록에서 제외했습니다. 생성 기록은 보존했습니다: ${setId}`)}catch(error){note(error.message,true)}}
async function requeueH3CandidateSet(setId,button){const set=(h3State.candidate_sets||[]).find(row=>row.candidate_set_id===setId),count=Number(set?.candidate_count||(set?.candidate_job_ids||[]).length||0),mode=String(set?.generation_mode||'r2v').toUpperCase();if(!confirm(`${set?.source_clip_id||setId}\n\n기존 ${mode} 설정과 Picture를 유지하고 후보 ${count}개를 새 랜덤 Seed로 다시 큐에 등록할까요?\n기존 후보와 선택 결과는 그대로 유지됩니다.`))return;const originalLabel=button?.textContent||'다시 후보로 등록하기';try{if(button){button.disabled=true;button.textContent='후보 등록 중…'}const out=await api(`/api/h3/candidate-sets/${encodeURIComponent(setId)}/requeue`,{method:'POST',headers:{'content-type':'application/json'},body:'{}'});await refreshH3State(true);note(`후보군을 다시 등록했습니다: ${out.candidate_set_id} · 후보 ${out.candidate_count}개`)}catch(error){if(button?.isConnected){button.disabled=false;button.textContent=originalLabel}note(error.message,true)}}
function syncH3CandidateSetActions(container){container?.querySelectorAll('[data-h3-candidate-actions]').forEach(actions=>{const set=(h3State.candidate_sets||[]).find(row=>row.candidate_set_id===actions.dataset.h3CandidateActions);if(!set)return;const state=h3CandidateSetRuntimeState(set),selected=h3CandidateSetHasSelection(set),force=actions.querySelector('[data-h3-force-candidate-set]'),remove=actions.querySelector('[data-h3-delete-candidate-set]');if(force){force.hidden=state.terminal;force.disabled=state.cancelRequested;force.textContent=state.cancelRequested?'강제종료 처리 중':'현재 큐 강제종료'}if(remove){remove.disabled=!state.terminal||selected;remove.title=selected?'선택된 후보가 있어 삭제할 수 없습니다. 먼저 후보 선택을 취소하세요.':state.terminal?'완료된 미선택 후보군을 목록에서 제외':'실행 중에는 삭제할 수 없습니다. 먼저 큐를 강제종료하세요.'}})}
