const syncH3CandidateSetActionsWithoutRequeue=syncH3CandidateSetActions;
syncH3CandidateSetActions=function(container){syncH3CandidateSetActionsWithoutRequeue(container);mountH3CandidateRequeueButtons(container);if(container?.id==='h3CandidateSets'){mountH3CandidateStoryboards(container);syncH3CandidatePageBulkActions()}}
function decorateH3CandidateRounds(container){
 container?.querySelectorAll('[data-h3-candidate-set]').forEach(article=>{
  const set=(h3State.candidate_sets||[]).find(row=>row.candidate_set_id===article.dataset.h3CandidateSet);if(!set)return;
  const cards=[...article.querySelectorAll('.h3-candidate-card')],headMeta=article.querySelector('.h3-candidate-set-head small'),promptSummary=article.querySelector(':scope > p'),labels=(set.prompt_variants||[]).map(row=>row.variant_id).join('·');
  if(headMeta&&!headMeta.dataset.candidateDecorated){headMeta.textContent=`후보 ${(set.candidate_job_ids||[]).length}개 · ${headMeta.textContent}`;headMeta.dataset.candidateDecorated='1'}
  if(promptSummary){const distinctPrompts=new Set((set.prompt_variants||[]).map(row=>String(row.video_prompt||''))).size,base=set.independent_prompts&&distinctPrompts>1?`기존 독립 프롬프트 기록 · ${labels}`:`단일 프롬프트 · Seed별 후보 ${(set.candidate_job_ids||[]).length}개`;promptSummary.className='h3-candidate-version-note';promptSummary.textContent=base}
  cards.forEach((card,index)=>{const jobId=set.candidate_job_ids?.[index],request=h3Job(jobId)?.request||{},title=card.querySelector('div>b'),variantId=request.prompt_variant_id||request.candidate_index||index+1,variantLabel=request.prompt_variant_label||`후보 ${variantId}`,variant=(set.prompt_variants||[]).find(row=>String(row.variant_id)===String(request.prompt_variant_id||''))||(set.prompt_variants||[])[index],variantPrompt=variant?.video_prompt||set.prompt||'';if(title)title.textContent=`후보 ${variantId} · ${variantLabel}`;if(!card.querySelector('.h3-embedding-effect'))card.querySelector(':scope > div')?.insertAdjacentHTML('afterend',h3EmbeddingEffectBadge(request,variantPrompt))})
 })
}
