function activeModelTestModels(){return(modelTestState.models||[]).filter(item=>item.legacy_read_only!==true)}
function syncModelTestResolution(){const select=$('#testSessionResolution'),modelSelect=$('#testSessionModel');if(!select||!modelSelect)return;const modelId=modelSelect.value;if(select.dataset.modelId===modelId)return;const model=(modelTestState.models||[]).find(item=>item.model_id===modelId);if(isMiniMaxH3TestModel(model))select.value='832x480';else if(select.value==='832x480')select.value='768x432';select.dataset.modelId=modelId}
