 const promptHtml=prompt?`<div class="model-test-canonical-prompt"><div><b>실제 입력 영문 프롬프트</b><small>canonical · ${durationLabel} · SHA-256 ${esc(prompt.prompt_sha256.slice(0,12))}…</small></div><p>${esc(prompt.prompt_text)}</p><button type="button" data-copy-test-prompt="${esc(item.case_version_id)}">프롬프트 복사</button></div>`:'<div class="model-test-canonical-prompt missing"><b>실제 입력 프롬프트 없음</b></div>';
