 $$('[data-copy-r2v-reference-all]').forEach(button=>button.onclick=async()=>{const item=findModelTestCase(button.dataset.copyR2vReferenceAll),slots=item?.contract?.reference_slots||[];if(!slots.length)return;const text=slots.map(slot=>`<Picture ${slot.picture_index}> · ${slot.label_ko}\n${slot.image_generation_prompt}`).join('\n\n---\n\n');try{await copyTextToClipboard(text);note(`레퍼런스 이미지 Prompt ${slots.length}개를 모두 복사했습니다.`)}catch(error){note(error.message,true)}});
 $$('[data-copy-test-prompt]').forEach(button=>button.onclick=async()=>{const cases=(modelTestState.suites||[]).flatMap(suite=>suite.cases||[]),item=cases.find(row=>row.case_version_id===button.dataset.copyTestPrompt),prompt=(item?.prompts||[]).find(row=>row.language==='en'&&row.prompt_kind==='canonical');if(!prompt)return;try{await copyTextToClipboard(prompt.prompt_text);note('테스트 프롬프트를 복사했습니다.')}catch(error){note(error.message,true)}});
 $$('[data-test-asset-file]').forEach(input=>input.onchange=async()=>{const file=input.files?.[0];if(!file)return;try{input.disabled=true;const body=new FormData();body.set('file',file);body.set('role',input.dataset.testAssetRole);await api(`/api/model-tests/cases/${encodeURIComponent(input.dataset.testAssetFile)}/assets`,{method:'POST',body});await refreshModelTests();note(`테스트 자산 연결: ${file.name}`)}catch(error){note(error.message,true)}finally{input.disabled=false}});
 $$('[data-unlink-test-asset]').forEach(button=>button.onclick=async()=>{if(!confirm('이 테스트 케이스에서 참조 이미지 연결을 해제할까요?\n\n해시 자산 원본은 다른 테스트 재사용을 위해 보존됩니다.'))return;try{await api(`/api/model-tests/cases/${encodeURIComponent(button.dataset.unlinkTestAsset)}/assets`,{method:'DELETE',headers:{'content-type':'application/json'},body:JSON.stringify({role:button.dataset.testAssetRole})});await refreshModelTests();note('테스트 자산 연결을 해제했습니다.')}catch(error){note(error.message,true)}});
