function syncModelTestAnalysisControls(){
 const model=$('#modelTestAnalysisModel'),workflow=$('#modelTestAnalysisWorkflow');if(!model||!workflow)return;const oldModel=model.value,oldWorkflow=workflow.value;
 model.innerHTML=(modelTestState.models||[]).map(item=>testOption(item.model_id,`${item.display_name}${item.version?` · ${item.version}`:''}`)).join('')||'<option value="">등록 모델 없음</option>';
 if((modelTestState.models||[]).some(item=>item.model_id===oldModel))model.value=oldModel;
 const profiles=(modelTestState.workflows||[]).filter(item=>item.model_id===model.value);workflow.innerHTML='<option value="">워크플로우 선택</option>'+profiles.map(item=>testOption(item.workflow_profile_id,`${isR2VWorkflowProfile(item)?'R2V':'I2V'} · ${item.name} · ${item.profile_kind}`)).join('');if(profiles.some(item=>item.workflow_profile_id===oldWorkflow))workflow.value=oldWorkflow;
}
function confidenceLabel(value){return value==='supported'?'충분':value==='exploratory'?'탐색적':'근거 부족'}
async function runModelTestAnalysis(){
 const modelId=$('#modelTestAnalysisModel').value;if(!modelId){note('분석할 모델을 선택하세요.',true);return}const workflowId=$('#modelTestAnalysisWorkflow').value;if(!workflowId){note('분석할 워크플로우를 선택하세요.',true);return}const query=new URLSearchParams({model_id:modelId,workflow_profile_id:workflowId});
 try{modelTestAnalysisState=await api('/api/model-tests/analysis?'+query);renderModelTestAnalysis()}catch(error){note(error.message,true)}
}
function renderModelTestAnalysis(){
 const box=$('#modelTestAnalysis');if(!box)return;if(!modelTestAnalysisState){box.innerHTML='<p class="muted">모델과 워크플로우를 선택해 분석하세요.</p>';return}
 const out=modelTestAnalysisState,s=out.summary;
 box.innerHTML=`<div class="model-test-analysis-summary"><span><b>${s.run_count}</b>실행</span><span><b>${s.completed_count}</b>완료</span><span><b>${s.reviewed_count}</b>리뷰</span><span><b>${Math.round(s.review_coverage*100)}%</b>리뷰 범위</span><span><b>${modelTestMetric(s.average_generation_seconds,'초')}</b>평균 생성</span></div><p class="muted">${esc(out.evidence_notice)}</p><h4>공통 역량</h4><div class="model-test-dimension-grid">${out.dimensions.map(item=>`<article class="confidence-${esc(item.confidence)}"><b>${esc(item.label)}</b><strong>${item.average_score==null?'-':Number(item.average_score).toFixed(2)}</strong><small>${esc(confidenceLabel(item.confidence))} · 근거 ${item.evidence_count}건</small></article>`).join('')}</div><h4>케이스별 근거</h4><div class="model-test-analysis-table"><table class="issues"><tr><th>케이스</th><th>완료</th><th>리뷰</th><th>평균</th><th>문제</th><th>신뢰도</th></tr>${out.cases.map(item=>`<tr><td>${esc(item.title)}</td><td>${item.completed_count}/${item.run_count}</td><td>${item.reviewed_count}</td><td>${item.average_score==null?'-':Number(item.average_score).toFixed(2)}</td><td>${item.issue_count}</td><td>${esc(confidenceLabel(item.confidence))}</td></tr>`).join('')}</table></div><h4>반복 문제와 정책 후보</h4><div class="model-test-policy-candidates">${out.policy_candidates.map(item=>`<article><div><b>${esc(candidateReviewCategoryLabels[item.category]||item.category)} · ${esc(item.subcategory)}</b><p>${esc(item.rule_text)}</p><small>${esc(confidenceLabel(item.confidence))} · 근거 실행 ${item.evidence_count}건</small></div><button type="button" data-approve-model-policy="${esc(item.candidate_id)}">정책으로 승인</button></article>`).join('')||'<p class="muted">리뷰 개선 제안에서 도출할 정책 후보가 없습니다.</p>'}</div><h4>활성 프롬프트 정책</h4><div class="model-test-active-policies">${out.active_policies.map(item=>`<article><div><b>${esc(item.dimension||'공통')}</b><p>${esc(item.rule_text)}</p><small>${esc(item.confidence)} · 근거 ${item.evidence_count}건</small></div><button type="button" class="danger" data-disable-model-policy="${esc(item.policy_id)}">비활성화</button></article>`).join('')||'<p class="muted">승인된 활성 정책이 없습니다.</p>'}</div><h4>승인 정책 프롬프트 가이드</h4><div class="model-test-prompt-guidance"><textarea readonly id="modelTestPromptGuidance">${esc(out.prompt_guidance||'')}</textarea><button type="button" id="copyModelTestPromptGuidance">가이드 복사</button></div>`;
 $("#copyModelTestPromptGuidance")?.addEventListener("click",async()=>{try{await copyTextToClipboard(out.prompt_guidance||"");note("승인 정책 프롬프트 가이드를 복사했습니다.")}catch(error){note(error.message,true)}});
 $$('[data-approve-model-policy]').forEach(button=>button.onclick=()=>approveModelTestPolicy(button.dataset.approveModelPolicy));$$('[data-disable-model-policy]').forEach(button=>button.onclick=()=>disableModelTestPolicy(button.dataset.disableModelPolicy));
}
async function approveModelTestPolicy(candidateId){
 const candidate=(modelTestAnalysisState?.policy_candidates||[]).find(item=>item.candidate_id===candidateId);if(!candidate)return;if(!confirm(`다음 규칙을 프롬프트 정책으로 승인할까요?\n\n${candidate.rule_text}\n\n신뢰도: ${confidenceLabel(candidate.confidence)} · 근거 ${candidate.evidence_count}건`))return;
 try{await api('/api/model-tests/policies',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({model_id:modelTestAnalysisState.scope.model_id,workflow_profile_id:modelTestAnalysisState.scope.workflow_profile_id,dimension:candidate.dimension,rule_text:candidate.rule_text,evidence_run_ids:candidate.evidence_run_ids})});await runModelTestAnalysis();note('프롬프트 정책을 승인했습니다.')}catch(error){note(error.message,true)}
}
async function disableModelTestPolicy(policyId){
 if(!confirm('이 프롬프트 정책을 비활성화할까요? 기록은 삭제하지 않습니다.'))return;try{await api(`/api/model-tests/policies/${encodeURIComponent(policyId)}`,{method:'PATCH',headers:{'content-type':'application/json'},body:JSON.stringify({active:false})});await runModelTestAnalysis();note('정책을 비활성화했습니다.')}catch(error){note(error.message,true)}
}
function modelTestRetestControls(runs){
 const cases=[];for(const run of runs){if(cases.some(item=>item.case_version_id===run.case_version_id))continue;const related=runs.filter(item=>item.case_version_id===run.case_version_id),suggested=related.some(item=>item.status==='failed'||(item.review&&item.review.verdict!=='acceptable'));cases.push({case_version_id:run.case_version_id,title:run.title,suggested})}
 if(!cases.length)return'';return `<div class="model-test-retest"><div><b>선택 케이스 후속 재시험</b><small>같은 모델·워크플로우·어댑터로 새 계획을 만듭니다.</small></div><div class="model-test-retest-cases">${cases.map(item=>`<label><input type="checkbox" data-model-retest-case value="${esc(item.case_version_id)}" ${item.suggested?'checked':''}> ${esc(item.title)}</label>`).join('')}</div><label>반복<input id="modelTestRetestRepetitions" type="number" min="1" max="10" value="1"></label><button type="button" id="createModelTestFollowup">후속 세션 생성</button></div>`
}
async function createModelTestFollowup(){
 if(!modelTestActiveResults)return;const caseIds=$$('[data-model-retest-case]:checked').map(input=>input.value);if(!caseIds.length){note('재시험할 케이스를 선택하세요.',true);return}const repetitions=Number($('#modelTestRetestRepetitions').value||1);
 try{const out=await api(`/api/model-tests/sessions/${encodeURIComponent(modelTestActiveResults.session.session_id)}/followup`,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({case_version_ids:caseIds,repetitions,reason:'user_selected_followup',notes:'결과 검수에서 선택한 후속 재시험'})});modelTestActiveResults=null;await refreshModelTests();note(`후속 세션 생성: ${out.session_id} · ${out.case_count}개 케이스`)}catch(error){note(error.message,true)}
}
async function downloadModelTestExport(format){
 try{const key=sessionStorage.getItem('h3-key')||'',headers={};if(key)headers['x-access-key-b64']=asciiKey(key);const response=await fetch(`/api/model-tests/export?format=${encodeURIComponent(format)}`,{headers});if(response.status===401){clearRejectedAccessKey(key);const entered=await requestAccessKey();if(entered)return downloadModelTestExport(format)}if(!response.ok)throw Error((await response.json()).error||`내보내기 오류 ${response.status}`);const blob=await response.blob(),disposition=response.headers.get('content-disposition')||'',match=disposition.match(/filename="?([^";]+)"?/i),filename=match?.[1]||`model_benchmark.${format}`,url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=filename;document.body.appendChild(link);link.click();link.remove();URL.revokeObjectURL(url);note(`${format.toUpperCase()} 내보내기 완료`)}catch(error){note(error.message,true)}
}
$('#modelTestAnalysisModel')?.addEventListener('change',()=>{syncModelTestAnalysisControls();modelTestAnalysisState=null;renderModelTestAnalysis()});$('#runModelTestAnalysis')?.addEventListener('click',runModelTestAnalysis);$('#exportModelTestsJson')?.addEventListener('click',()=>downloadModelTestExport('json'));$('#exportModelTestsCsv')?.addEventListener('click',()=>downloadModelTestExport('csv'));
let modelTestEventRefreshTimer=null,modelTestEventRefreshRunning=false;
async function refreshModelTestsFromEvent(){if(!['model-management','model-tests','r2v-tests'].includes(currentPage))return;if(modelTestEventRefreshRunning)return;modelTestEventRefreshRunning=true;try{await refreshModelTests()}catch(error){console.warn('모델 테스트 이벤트 갱신 실패',error)}finally{modelTestEventRefreshRunning=false}}
function scheduleModelTestEventRefresh(){clearTimeout(modelTestEventRefreshTimer);modelTestEventRefreshTimer=setTimeout(refreshModelTestsFromEvent,400)}
const MODEL_TEST_REVIEW_DRAFT_KEY='h3-model-test-review-drafts-v1';
const modelTestReviewDrafts=()=>{try{return JSON.parse(localStorage.getItem(MODEL_TEST_REVIEW_DRAFT_KEY)||'{}')}catch{return{}}};
function modelTestReviewEmpty(){return{verdict:'unrated',positive_note:'',overall_note:'',scores:{},issues:[]}}
function modelTestMetric(value,suffix=''){return value==null||value===''?'-':`${Number(value).toLocaleString(undefined,{maximumFractionDigits:1})}${suffix}`}
function modelTestComparisonCard(group,labels,r2v){
 const empty=r2v?'아직 저장된 R2V 검수 점수가 없습니다.':'아직 저장된 I2V 검수 점수가 없습니다.';
 const solAttn=r2vSolAttnSettingsSummary(group.workflow_settings?.sol_attn),settings=`${solAttn?`<small class="model-test-workflow-settings">Sol-Attn · ${esc(solAttn)}</small>`:''}`;
 return `<article><div class="model-test-comparison-title"><h4>${esc(group.model_name)}</h4><span class="model-test-workflow-kind ${r2v?'r2v':'i2v'}">${r2v?'R2V':'I2V'}</span></div><small>${esc(group.workflow_name)} · ${esc(group.profile_kind)}</small>${settings}<div class="model-test-comparison-meta"><span>세션 ${esc(group.session_count||0)}</span><span>완료 ${esc(group.completed_count||0)}/${esc(group.run_count||0)}</span><span>리뷰 ${esc(group.reviewed_count||0)}</span><span>평균 생성 ${modelTestMetric(group.average_generation_seconds,'초')}</span></div><div class="model-test-score-summary">${Object.entries(group.average_scores||{}).map(([key,value])=>`<span><b>${esc(labels[key]||key)}</b>${Number(value).toFixed(2)}</span>`).join('')||`<small class="muted">${empty}</small>`}</div></article>`;
}
function renderModelTestComparison(){
 const box=$('#modelTestComparison');if(!box)return;const groups=modelTestComparisonState.groups||[],labels=modelTestComparisonState.score_dimensions||{},workflows=modelTestState.workflows||[];
 const isR2VGroup=group=>group.input_mode==='h3_r2v_multi_reference'||isR2VWorkflowProfile(workflows.find(item=>item.workflow_profile_id===group.workflow_profile_id));
 const i2vGroups=groups.filter(group=>!isR2VGroup(group)),r2vGroups=groups.filter(isR2VGroup);
 const section=(title,description,kind,items)=>`<section class="model-test-comparison-section ${kind}"><div class="model-test-comparison-section-head"><div><h4>${title}</h4><p>${description}</p></div><span>${items.length}개 비교 구성</span></div>${items.length?`<div class="model-test-comparison-grid">${items.map(group=>modelTestComparisonCard(group,labels,kind==='r2v')).join('')}</div>`:`<p class="model-test-comparison-empty">등록된 ${kind==='r2v'?'R2V':'I2V'} 테스트 세션이 없습니다.</p>`}</section>`;
 box.innerHTML=section('일반 I2V 워크플로우','일반 이미지 기반 테스트와 I2V 검수 점수만 표시합니다.','i2v',i2vGroups)+section('R2V 워크플로우','다중 참조 R2V 테스트와 R2V 전용 검수 점수만 표시합니다.','r2v',r2vGroups);
}
function modelTestOpenRunIds(){return new Set($$('#modelTestResults details[data-model-test-run][open], #r2vTestResults details[data-model-test-run][open]').map(item=>item.dataset.modelTestRun))}
function modelTestResultsBox(session=modelTestActiveResults?.session){return isR2VSession(session)?$('#r2vTestResults'):$('#modelTestResults')}
async function loadModelTestResults(sessionId,{scroll=false,preserveOpen=true}={}){
 const openRunIds=preserveOpen?modelTestOpenRunIds():new Set(),scrollX=window.scrollX,scrollY=window.scrollY;
 try{const out=await api(`/api/model-tests/sessions/${encodeURIComponent(sessionId)}/results`);modelTestActiveResults=out;renderModelTestResults(openRunIds);if(scroll)modelTestResultsBox(out.session)?.scrollIntoView({behavior:'smooth',block:'start'});else requestAnimationFrame(()=>window.scrollTo(scrollX,scrollY))}catch(error){note(error.message,true)}
}

function modelTestReviewSummaries(run){
 const rows=[[(String(run.ai_review?.rubric_version||'').startsWith('r2v_')?'보관된 R2V AI 검수 · 읽기 전용':'보관된 AI 검수 · 읽기 전용'),run.ai_review],["사람 검수",run.human_review]].filter(([,review])=>review);
 if(!rows.length)return '<p class="muted">아직 저장된 리뷰가 없습니다.</p>';
 return rows.map(([label,review])=>{
  const checks=review.event_checks||[],forbidden=review.forbidden_checks||[],references=review.reference_checks||[],dialogue=review.dialogue_checks||[],bindings=review.subject_binding_checks||[],shot=review.shot_structure_check||{},gate=review.enforcement||{};
  const confidence=review.confidence==null?'':` · 신뢰도 ${Math.round(Number(review.confidence)*100)}%`,strict=review.rubric_version==='strict_prompt_compliance_v2';
  const r2v=String(review.rubric_version||'').startsWith('r2v_'),storyboardV7=review.rubric_version==='r2v_storyboard_action_flow_v7',storyboardV6=review.rubric_version==='r2v_storyboard_grounded_v6',generalV5=review.rubric_version==='r2v_general_reference_grounded_v5',storyboardV4=review.rubric_version==='r2v_multishot_storyboard_dialogue_grounded_v4',storyboardV3=review.rubric_version==='r2v_storyboard_dialogue_grounded_v3',storyboardV2=storyboardV7||storyboardV6||storyboardV4||storyboardV3||review.rubric_version==='r2v_storyboard_grounded_v2';
  const referenceRows=references.map(item=>`<li><strong>Picture ${esc(item.picture_index)} · ${esc(item.status||'uncertain')}</strong> · ${esc(item.label_ko||item.role||'')}<small>${esc(item.evidence_ko||'')}</small>${(item.panel_beat_checks||[]).length?`<ul>${item.panel_beat_checks.map(panel=>`<li>${storyboardV4?'Shot':'패널'} ${esc(panel.shot_index||panel.panel_index)} · <strong>${esc(panel.status)}</strong><small>${esc(panel.evidence_ko||'')}</small></li>`).join('')}</ul>`:''}</li>`).join('');
  const dialogueRows=dialogue.map(item=>`<li><strong>${esc(item.speaker_id||item.speaker)} · ${esc(item.line_ko||'')}</strong><small>대사 ${esc(item.exact_text_status)} · 화자 ${esc(item.speaker_identity_status)} · 순서 ${esc(item.order_status)} · 립싱크 ${esc(item.lip_sync_status)} · 비화자 입 ${esc(item.non_speaker_mouth_status)} · ${esc(item.evidence_ko||'')}</small></li>`).join('');
  const bindingRows=bindings.map(item=>`<li><strong>Subject ${esc(item.subject_index)} · Picture ${esc(item.picture_index)} · ${esc(item.status)}</strong><small>${esc(item.label_ko||item.role||'')} · ${esc(item.evidence_ko||'')}</small></li>`).join('');
  const shotRow=Object.keys(shot).length?(generalV5?`<div class="model-test-event-checks"><b>일반 숏 구조·카메라</b><p>샷 수·순서 ${esc(shot.shot_count_order_status)} · 컷 타이밍 ${esc(shot.cut_timing_status)} · 화면 방향 ${esc(shot.screen_direction_status)} · 카메라 ${esc(shot.camera_plan_status)}</p><small>${esc(shot.evidence_ko||'')}</small></div>`:storyboardV7?`<div class="model-test-event-checks"><b>스토리보드 액션 연결·속도</b><p>샷 수·순서 ${esc(shot.shot_count_order_status)} · 컷 타이밍 ${esc(shot.cut_timing_status)} · 액션 연결 ${esc(shot.action_flow_status)} · 속도·리듬 ${esc(shot.pacing_status)} · 화면 방향 ${esc(shot.screen_direction_status)} · 패널 화면 누출 ${esc(shot.storyboard_layout_leak)}</p><small>${esc(shot.evidence_ko||'')}</small></div>`:storyboardV6||storyboardV4?`<div class="model-test-event-checks"><b>스토리보드 순서·상태·레이아웃</b><p>샷 수·순서 ${esc(shot.shot_count_order_status)} · 컷 타이밍 ${esc(shot.cut_timing_status)} · 화면 방향 ${esc(shot.screen_direction_status)} · 카메라 ${esc(shot.camera_plan_status)} · 패널 화면 누출 ${esc(shot.storyboard_layout_leak)}</p><small>${esc(shot.evidence_ko||'')}</small></div>`:`<div class="model-test-event-checks"><b>연속 샷·카메라·레이아웃</b><p>연속 샷 ${esc(shot.continuous_shot_status)} · 화면 방향 ${esc(shot.screen_direction_status)} · 카메라 ${esc(shot.camera_plan_status)} · 패널 화면 누출 ${esc(shot.storyboard_layout_leak)}</p><small>${esc(shot.evidence_ko||'')}</small></div>`):'';
  return `<section class="model-test-review-source"><b>${label} · ${esc(review.verdict)} · revision ${review.revision} · 문제 ${(review.issues||[]).length}건${confidence}</b>${strict?`<p><strong>엄격 프롬프트 게이트 v2 · ${gate.gate_passed?'통과':'미통과'}</strong> · 필수 행동 ${esc(gate.required_verified||0)}/${esc(gate.required_total||0)} · 금지 실패 관찰 ${esc(gate.forbidden_observed||0)} · 불확실 ${esc(gate.forbidden_uncertain||0)}</p>`:''}${r2v?`<p><strong>${storyboardV7?'R2V 스토리보드 액션 연결 게이트 v7':storyboardV6?'R2V 스토리보드 충실도 게이트 v6':generalV5?'R2V 공통 참조·프롬프트 게이트 v5':storyboardV4?'R2V 멀티샷·대사 게이트 v4':storyboardV3?'R2V 스토리보드·대사 게이트 v3':storyboardV2?'R2V 멀티패널 스토리보드 게이트 v2':'R2V 참조 기반 게이트 v1'} · ${gate.gate_passed?'통과':'미통과'}</strong> · 참조 일치 ${esc(gate.reference_matched||0)}/${esc(gate.reference_total||0)}${storyboardV2?` · 스토리보드 샷 ${esc(gate.storyboard_shot_verified??gate.storyboard_panel_verified??0)}/${esc(gate.storyboard_shot_total??gate.storyboard_panel_total??0)}`:''}${generalV5||storyboardV7||storyboardV6||storyboardV4||storyboardV3?` · 대사 모순 ${esc(gate.dialogue_hard_contradicted||0)} · Subject 모순 ${esc(gate.subject_binding_major_mismatch||0)}`:''} · 사람 확인 ${gate.human_review_required?'필요':'불필요'}</p>`:''}<p>${esc(review.overall_note||'메모 없음')}</p><div class="model-test-score-summary">${Object.entries(review.scores||{}).map(([key,value])=>`<span><b>${esc(modelTestActiveResults.score_dimensions[key]||key)}</b>${Number(value).toFixed(1)}</span>`).join('')}</div>${references.length?`<div class="model-test-event-checks"><b>참조 이미지 판정</b><ul>${referenceRows}</ul></div>`:''}${bindings.length?`<div class="model-test-event-checks"><b>Subject 역할 바인딩</b><ul>${bindingRows}</ul></div>`:''}${dialogue.length?`<div class="model-test-event-checks"><b>화자·대사·립싱크</b><ul>${dialogueRows}</ul></div>`:''}${shotRow}${checks.length?`<div class="model-test-event-checks"><b>필수 사건 판정</b><ul>${checks.map(item=>`<li><strong>${esc(item.status||'uncertain')}</strong> · ${esc(item.requirement_ko||'')}<small>${esc(item.evidence_ko||'')}</small></li>`).join('')}</ul></div>`:''}${forbidden.length?`<div class="model-test-event-checks"><b>금지 실패 판정</b><ul>${forbidden.map(item=>`<li><strong>${esc(item.status||'uncertain')}</strong> · ${esc(item.failure_ko||'')}<small>${esc(item.evidence_ko||'')}</small></li>`).join('')}</ul></div>`:''}</section>`;
 }).join('');
}
function modelTestRunMedia(run,ready){
 if(!ready||!run.video_url)return '<div class="video-placeholder">완료된 영상 없음</div>';
 const id=String(run.run_id),jobId=String(run.job_id||''),playing=modelTestPlayingRuns.has(id);
 if(playing)return `<div class="model-test-run-media is-playing"><video controls autoplay preload="metadata" src="${esc(run.video_url)}"></video><button type="button" class="mini" data-model-test-video-close="${esc(id)}">썸네일로</button></div>`;
 const thumbnail=`/api/jobs/${encodeURIComponent(jobId)}/video-thumbnail`,fallback=`/api/jobs/${encodeURIComponent(jobId)}/thumbnail?max=960`;
 return `<button type="button" class="model-test-video-thumbnail" data-model-test-video-play="${esc(id)}"><img src="${esc(thumbnail)}" data-fallback="${esc(fallback)}" alt="${esc(run.title||'생성 영상')} 썸네일" loading="lazy"><span>영상 재생</span></button>`;
}
function bindModelTestVideoPreviews(){
 $$('[data-model-test-video-play]').forEach(button=>button.onclick=()=>{modelTestPlayingRuns.add(String(button.dataset.modelTestVideoPlay));renderModelTestResults(modelTestOpenRunIds());requestAnimationFrame(()=>$$('[data-model-test-run]').find(row=>row.dataset.modelTestRun===String(button.dataset.modelTestVideoPlay))?.querySelector('video')?.play().catch(()=>{}))});
 $$('[data-model-test-video-close]').forEach(button=>button.onclick=()=>{modelTestPlayingRuns.delete(String(button.dataset.modelTestVideoClose));renderModelTestResults(modelTestOpenRunIds())});
 $$('.model-test-video-thumbnail img').forEach(image=>image.onerror=()=>{const fallback=image.dataset.fallback;if(fallback&&image.src!==new URL(fallback,location.href).href){image.src=fallback;image.onerror=null}});
}
function renderModelTestResults(openRunIds=new Set()){
 const box=modelTestResultsBox();if(!box)return;if(!modelTestActiveResults){box.innerHTML='<p class="muted">검수할 테스트 세션을 선택하세요.</p>';return}
 const session=modelTestActiveResults.session,runs=modelTestActiveResults.runs||[];
 const humanDone=runs.filter(run=>run.human_review).length;
 box.innerHTML=`<div class="model-test-result-head"><div><b>${esc(session.session_id)}</b><small>${esc(session.model_name)} · ${esc(session.workflow_name)} · ${esc(session.status)}</small></div><div class="model-test-ai-progress"><span>사람 리뷰 ${humanDone}/${runs.length}</span><progress max="${runs.length||1}" value="${humanDone}"></progress><small>유효 리뷰(보관 AI 포함) ${runs.filter(run=>run.review).length}/${runs.length}</small></div></div>${modelTestRetestControls(runs)}<div class="model-test-result-list">${runs.map(run=>{const review=run.review,ready=run.status==='completed';return `<details class="model-test-result-card" data-model-test-run="${esc(run.run_id)}" ${openRunIds.has(String(run.run_id))?'open':''}><summary><span class="model-test-order">${String(run.ordering).padStart(2,'0')}</span><div><b>${esc(run.title)}${run.repetition>1?` · 반복 ${run.repetition}`:''}</b><small>${esc(run.status)} · seed ${esc(run.seed_text||'-')}</small></div>${run.ai_review&&!run.human_review?'<span class="model-test-ai-state ai-completed">보관 AI 검수</span>':''}</summary><div class="model-test-result-body"><div>${modelTestRunMedia(run,ready)}<div class="model-test-run-metrics"><span>생성 ${modelTestMetric(run.generation_seconds,'초')}</span><span>${esc(run.width||'-')}×${esc(run.height||'-')}</span><span>${modelTestMetric(run.fps,' FPS')}</span><span>GPU ${formatBytes(run.peak_gpu_memory_bytes)}</span></div></div><div class="model-test-contract"><p>${esc(run.intent_ko)}</p><b>필수 사건</b><ul>${(run.contract.required_events||[]).map(value=>`<li>${esc(value)}</li>`).join('')}</ul><b>금지 실패</b><ul>${(run.contract.forbidden_failures||[]).map(value=>`<li>${esc(value)}</li>`).join('')}</ul></div><div class="model-test-review-summary">${modelTestReviewSummaries(run)}<button type="button" data-model-test-review="${esc(run.run_id)}" ${ready?'':'disabled'}>${run.human_review?'사람 리뷰 수정 · 새 revision':'사람 리뷰 작성'}</button></div></div></details>`}).join('')}</div>`;
 bindModelTestVideoPreviews(); $$('[data-model-test-review]').forEach(button=>button.onclick=()=>openModelTestReview(button.dataset.modelTestReview));
 $("#createModelTestFollowup")?.addEventListener("click",createModelTestFollowup);
}
function collectModelTestReview(){
 const form=$('#modelTestReviewForm'),scores={};$$('#modelTestReviewScores [data-score-dimension]').forEach(input=>{if(input.value!=='')scores[input.dataset.scoreDimension]=Number(input.value)});
 return{verdict:form.elements.verdict.value,positive_note:form.elements.positive_note.value.trim(),overall_note:form.elements.overall_note.value.trim(),scores,issues:$$('#modelTestReviewIssues [data-model-test-issue]').map(row=>{const value=name=>row.querySelector(`[data-model-test-field="${name}"]`)?.value??'';return{issue_id:row.dataset.issueId,category:value('category'),subcategory:value('subcategory').trim(),severity:value('severity'),start_seconds:value('start_seconds')===''?null:Number(value('start_seconds')),end_seconds:value('end_seconds')===''?null:Number(value('end_seconds')),expected:value('expected').trim(),observed:value('observed').trim(),difference:value('difference').trim(),cause_hypothesis:value('cause_hypothesis').trim(),suggestion:value('suggestion').trim()}})}
}
function modelTestSubcategoryOptions(category,selected){
 const entries=candidateReviewSubcategories[category]||candidateReviewSubcategories.other;
 const current=String(selected||'other');
 const preserved=entries[current]?'':`<option value="${esc(current)}" selected>${esc(`기존 세부 유형: ${current}`)}</option>`;
 return `${preserved}${Object.entries(entries).map(([value,label])=>`<option value="${esc(value)}" ${value===current?'selected':''}>${esc(label)}</option>`).join('')}`;
}
function renderModelTestReviewIssues(){
 const box=$('#modelTestReviewIssues'),issues=modelTestReviewData?.issues||[];if(!issues.length){box.innerHTML='<div class="candidate-review-empty">등록된 문제가 없습니다. 문제가 보이면 「문제 추가」를 누르세요.</div>';return}
 box.innerHTML=issues.map((issue,index)=>`<details class="candidate-review-issue" data-model-test-issue data-issue-id="${esc(issue.issue_id||uiId())}" open><summary><b>문제 ${index+1}</b><span>${esc(candidateReviewCategoryLabels[issue.category]||issue.category||'기타')}</span><span>${esc(issue.severity||'major')}</span></summary><div class="candidate-review-issue-body"><div class="candidate-review-grid"><label>문제 유형<select data-model-test-field="category">${Object.entries(candidateReviewCategoryLabels).map(([value,label])=>`<option value="${esc(value)}" ${value===(issue.category||'other')?'selected':''}>${esc(label)}</option>`).join('')}</select></label><label>세부 유형<select data-model-test-field="subcategory" required>${modelTestSubcategoryOptions(issue.category||'other',issue.subcategory||'other')}</select></label><label>심각도<select data-model-test-field="severity"><option value="minor" ${issue.severity==='minor'?'selected':''}>경미</option><option value="major" ${issue.severity==='major'?'selected':''}>주요</option><option value="critical" ${issue.severity==='critical'?'selected':''}>치명적</option></select></label><label>시작(초)<input data-model-test-field="start_seconds" type="number" min="0" step="0.1" value="${issue.start_seconds??''}"></label><label>종료(초)<input data-model-test-field="end_seconds" type="number" min="0" step="0.1" value="${issue.end_seconds??''}"></label></div><div class="candidate-review-text-grid"><label>의도한 표현<textarea data-model-test-field="expected" required>${esc(issue.expected||modelTestReviewContext?.intentKo||'')}</textarea></label><label>영상의 실제 출력<textarea data-model-test-field="observed" required>${esc(issue.observed||'')}</textarea></label><label>차이 설명<textarea data-model-test-field="difference">${esc(issue.difference||'')}</textarea></label><label>원인 추정<textarea data-model-test-field="cause_hypothesis">${esc(issue.cause_hypothesis||'')}</textarea></label><label class="wide">개선 제안<textarea data-model-test-field="suggestion">${esc(issue.suggestion||'')}</textarea></label></div><button type="button" class="danger mini" data-remove-model-test-issue="${index}">이 문제 삭제</button></div></details>`).join('');
 $$('[data-model-test-field="category"]').forEach((select,index)=>select.onchange=()=>{modelTestReviewData=collectModelTestReview();const category=select.value,first=Object.keys(candidateReviewSubcategories[category]||candidateReviewSubcategories.other)[0];modelTestReviewData.issues[index].category=category;modelTestReviewData.issues[index].subcategory=first;renderModelTestReviewIssues();persistModelTestReviewDraft()});
 $$('[data-remove-model-test-issue]').forEach(button=>button.onclick=()=>{modelTestReviewData=collectModelTestReview();modelTestReviewData.issues.splice(Number(button.dataset.removeModelTestIssue),1);renderModelTestReviewIssues();persistModelTestReviewDraft()});
}
function persistModelTestReviewDraft(){if(!modelTestReviewContext||!$('#modelTestReviewDialog').open)return;modelTestReviewData=collectModelTestReview();const drafts=modelTestReviewDrafts();drafts[modelTestReviewContext.runId]=modelTestReviewData;localStorage.setItem(MODEL_TEST_REVIEW_DRAFT_KEY,JSON.stringify(drafts));$('#modelTestReviewSaveStatus').textContent='로컬 초안 저장됨'}
async function openModelTestReview(runId){
 try{const out=await api(`/api/model-tests/runs/${encodeURIComponent(runId)}/review`),run=out.run,draft=modelTestReviewDrafts()[runId];modelTestReviewContext={runId,sessionId:run.session_id,intentKo:run.intent_ko,draftTimer:null};modelTestReviewData=draft||out.review||modelTestReviewEmpty();modelTestReviewData.issues=(modelTestReviewData.issues||[]).map(item=>({...item,issue_id:item.issue_id||uiId()}));const form=$('#modelTestReviewForm');form.elements.verdict.value=modelTestReviewData.verdict||'unrated';form.elements.positive_note.value=modelTestReviewData.positive_note||'';form.elements.overall_note.value=modelTestReviewData.overall_note||'';$('#modelTestReviewTitle').textContent=`${run.case_title} · 반복 ${run.repetition}`;$('#modelTestReviewMeta').textContent=`${run.model_name} · ${run.workflow_name} · ${run.run_id}${draft?' · 로컬 초안 복원':''}`;$('#modelTestReviewVideo').innerHTML=run.video_url?`<video controls preload="metadata" src="${esc(run.video_url)}"></video><p>${esc(run.intent_ko)}</p>`:'';$('#modelTestReviewScores').innerHTML=Object.entries(out.score_dimensions||{}).map(([key,label])=>`<label>${esc(label)}<select data-score-dimension="${esc(key)}"><option value="">평가 안 함</option>${[0,1,2,3,4,5].map(value=>`<option value="${value}" ${Number(modelTestReviewData.scores?.[key])===value?'selected':''}>${value}점</option>`).join('')}</select></label>`).join('');$('#modelTestReviewSaveStatus').textContent=out.review?`서버 저장본 revision ${out.review.revision}`:'새 리뷰';renderModelTestReviewIssues();$('#modelTestReviewDialog').showModal()}catch(error){note(error.message,true)}
}
function closeModelTestReview(){if($('#modelTestReviewDialog').open){persistModelTestReviewDraft();$('#modelTestReviewDialog').close()}}
$('#modelTestReviewAddIssue').onclick=()=>{modelTestReviewData=collectModelTestReview();modelTestReviewData.issues.push({issue_id:uiId(),category:'other',subcategory:'other',severity:'major',start_seconds:null,end_seconds:null,expected:modelTestReviewContext?.intentKo||'',observed:'',difference:'',cause_hypothesis:'',suggestion:''});renderModelTestReviewIssues();persistModelTestReviewDraft()};
$('#modelTestReviewClose').onclick=closeModelTestReview;$('#modelTestReviewCancel').onclick=closeModelTestReview;$('#modelTestReviewDialog').addEventListener('cancel',event=>{event.preventDefault();closeModelTestReview()});$('#modelTestReviewForm').oninput=()=>{clearTimeout(modelTestReviewContext?.draftTimer);if(modelTestReviewContext)modelTestReviewContext.draftTimer=setTimeout(persistModelTestReviewDraft,250)};
$('#modelTestReviewForm').onsubmit=async event=>{event.preventDefault();if(!modelTestReviewContext)return;try{const payload=collectModelTestReview(),out=await api(`/api/model-tests/runs/${encodeURIComponent(modelTestReviewContext.runId)}/review`,{method:'PUT',headers:{'content-type':'application/json'},body:JSON.stringify(payload)}),drafts=modelTestReviewDrafts();delete drafts[modelTestReviewContext.runId];localStorage.setItem(MODEL_TEST_REVIEW_DRAFT_KEY,JSON.stringify(drafts));$('#modelTestReviewDialog').close();modelTestComparisonState=await api('/api/model-tests/comparison');await loadModelTestResults(modelTestReviewContext.sessionId,{scroll:false,preserveOpen:true});renderModelTestComparison();note(`모델 테스트 리뷰 revision ${out.review.revision} 저장 완료`)}catch(error){note(error.message,true)}};

